impl Document {
    pub(crate) fn compare_chapter(
        &self,
        other: &Document,
        a: &Chapter,
        b: &Chapter,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_chapter_model() != b.get_chapter_model() {
            return Err(format!("{path}: CHAPTER_MODEL mismatch"));
        }
        if a.get_help_entry() != b.get_help_entry() {
            return Err(format!("{path}: HELP_ENTRY mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_chapter_content(
        &self,
        _other: &Document,
        a: &ChapterContent,
        b: &ChapterContent,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_prms() != b.get_prms() {
            return Err(format!("{path}: PRMS mismatch"));
        }
        if a.get_topic_content() != b.get_topic_content() {
            return Err(format!("{path}: TOPIC_CONTENT mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_chapter_model(
        &self,
        _other: &Document,
        a: &ChapterModel,
        b: &ChapterModel,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_chapter() != b.get_chapter() {
            return Err(format!("{path}: CHAPTER mismatch"));
        }
        if a.get_chapter_content() != b.get_chapter_content() {
            return Err(format!("{path}: CHAPTER_CONTENT mismatch"));
        }
        if a.get_topic1() != b.get_topic1() {
            return Err(format!("{path}: TOPIC1 mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_chapter_or_msr_query(
        &self,
        other: &Document,
        a: &ChapterOrMsrQuery,
        b: &ChapterOrMsrQuery,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        let list_a = a.get_chapters();
        let list_b = b.get_chapters();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: CHAPTERS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .chapters
                .get(*x)
                .ok_or_else(|| format!("{path}.CHAPTERS[{index}]: id not found in own arena"))?;
            let y = other
                .chapters
                .get(*y)
                .ok_or_else(|| format!("{path}.CHAPTERS[{index}]: id not found in other arena"))?;
            self.compare_chapter(other, x, y, &format!("{path}.CHAPTERS[{index}]"))?;
        }
        if a.get_msr_query_chapter() != b.get_msr_query_chapter() {
            return Err(format!("{path}: MSR_QUERY_CHAPTER mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_predefined_chapter(
        &self,
        _other: &Document,
        a: &PredefinedChapter,
        b: &PredefinedChapter,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_chapter_model() != b.get_chapter_model() {
            return Err(format!("{path}: CHAPTER_MODEL mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_topic1(
        &self,
        other: &Document,
        a: &Topic1,
        b: &Topic1,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_help_entry() != b.get_help_entry() {
            return Err(format!("{path}: HELP_ENTRY mismatch"));
        }
        if a.get_topic_content() != b.get_topic_content() {
            return Err(format!("{path}: TOPIC_CONTENT mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_topic_content(
        &self,
        _other: &Document,
        a: &TopicContent,
        b: &TopicContent,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_block_level_content() != b.get_block_level_content() {
            return Err(format!("{path}: BLOCK_LEVEL_CONTENT mismatch"));
        }
        if a.get_table() != b.get_table() {
            return Err(format!("{path}: TABLE mismatch"));
        }
        if a.get_traceable_table() != b.get_traceable_table() {
            return Err(format!("{path}: TRACEABLE_TABLE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_topic_content_or_msr_query(
        &self,
        _other: &Document,
        a: &TopicContentOrMsrQuery,
        b: &TopicContentOrMsrQuery,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_msr_query_p1() != b.get_msr_query_p1() {
            return Err(format!("{path}: MSR_QUERY_P1 mismatch"));
        }
        if a.get_topic_content() != b.get_topic_content() {
            return Err(format!("{path}: TOPIC_CONTENT mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_topic_or_msr_query(
        &self,
        other: &Document,
        a: &TopicOrMsrQuery,
        b: &TopicOrMsrQuery,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_msr_query_topic1() != b.get_msr_query_topic1() {
            return Err(format!("{path}: MSR_QUERY_TOPIC1 mismatch"));
        }
        let list_a = a.get_topic1();
        let list_b = b.get_topic1();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: TOPIC1 length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .topic1s
                .get(*x)
                .ok_or_else(|| format!("{path}.TOPIC1[{index}]: id not found in own arena"))?;
            let y = other
                .topic1s
                .get(*y)
                .ok_or_else(|| format!("{path}.TOPIC1[{index}]: id not found in other arena"))?;
            self.compare_topic1(other, x, y, &format!("{path}.TOPIC1[{index}]"))?;
        }
        Ok(())
    }
}
